for(const a of articles){fs.writeFileSync(path.join(__dirname,'articles',`${a.slug}.html`),buildHTML(a,false).replace(/\r\n/g,'\n'),'utf8');fs.writeFileSync(path.join(__dirname,'articles','en',`${a.slug}.html`),buildHTML(a,true).replace(/\r\n/g,'\n'),'utf8');console.log(`Created: ${a.slug}`);}
